import{_ as t,a,o as i,a4 as n}from"./chunks/framework.-FZumj2l.js";const c=JSON.parse('{"title":"Generate Sitemap","description":"","frontmatter":{"outline":false,"examples":[{"id":"generate","title":"Generate Sitemap","description":"Build the actual XML files for a sitemap. Walks public categories, products, and pages and records the written paths.","query":"mutation CreateAdminMarketingSitemapGenerate(\\n  $input: createAdminMarketingSitemapGenerateInput!\\n) {\\n  createAdminMarketingSitemapGenerate(input: $input) {\\n    adminMarketingSitemapGenerate {\\n      sitemapId\\n      indexFile\\n      generatedSitemaps\\n      generatedAt\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/marketing/sitemaps/1\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminMarketingSitemapGenerate\\": {\\n      \\"adminMarketingSitemapGenerate\\": {\\n        \\"sitemapId\\": 1,\\n        \\"indexFile\\": \\"/sitemap.xml\\",\\n        \\"generatedSitemaps\\": [\\n          \\"/sitemap-products-1.xml\\"\\n        ],\\n        \\"generatedAt\\": \\"2026-06-23T13:00:00+05:30\\",\\n        \\"message\\": \\"Sitemap generated successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/marketing/search-seo/sitemaps-generate.md","filePath":"api/graphql-api/admin/marketing/search-seo/sitemaps-generate.md","lastUpdated":1783079210000}'),s={name:"api/graphql-api/admin/marketing/search-seo/sitemaps-generate.md"};function r(d,e,o,p,l,h){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="generate-sitemap" tabindex="-1">Generate Sitemap <a class="header-anchor" href="#generate-sitemap" aria-label="Permalink to &quot;Generate Sitemap&quot;">​</a></h1><p>Builds the actual XML files for a sitemap — the <strong>Generate</strong> action on the admin <strong>Marketing → Search &amp; SEO → Sitemaps</strong> screen. It walks the store&#39;s public categories, products, and pages, writes the index file plus per-batch XML files, and records their paths on the sitemap.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New here? Read the <a href="/api/graphql-api/admin/marketing/search-seo/sitemaps/">Sitemaps overview</a> for what a sitemap does and how its fields behave.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>createAdminMarketingSitemapGenerate</code></td><td>Mutation</td><td>Build the XML files for a sitemap</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.search_seo.sitemaps.edit</code> permission.</li><li>Pass the sitemap&#39;s IRI (e.g. <code>/api/admin/marketing/sitemaps/1</code>) as <code>id</code>. Use the <a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-list.html">list</a> query to discover valid ids.</li><li>Generation runs synchronously — the response carries the written paths once it finishes.</li><li>Creating or updating a sitemap does <strong>not</strong> auto-generate. Call this mutation explicitly to (re)build the files.</li><li>If sitemap generation is disabled in store configuration, the mutation still succeeds but writes no files (<code>generatedSitemaps</code> comes back empty).</li></ul><h2 id="input-fields" tabindex="-1">Input fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID</td><td>Yes</td><td>The sitemap&#39;s IRI</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>sitemapId</code></td><td>Int</td><td>Numeric id of the generated sitemap</td></tr><tr><td><code>indexFile</code></td><td>String</td><td>Path of the written index file</td></tr><tr><td><code>generatedSitemaps</code></td><td>Array</td><td>Paths of the per-batch product / category / page files</td></tr><tr><td><code>generatedAt</code></td><td>String</td><td>Timestamp the generation finished</td></tr><tr><td><code>message</code></td><td>String</td><td>Human-readable success message</td></tr></tbody></table>',11)]))}const g=t(s,[["render",r]]);export{c as __pageData,g as default};
